<template>
  <div class="container"><TopBar /><h1>Notificaciones y sonido</h1><section class="card"><h2>Estado del dispositivo</h2><p>Permiso de notificaciones: <strong>{{ permission }}</strong></p><p>Service Worker: <strong>{{ serviceWorker }}</strong></p><p>Las notificaciones push cuando la aplicación está cerrada requieren un backend con Web Push y claves VAPID. Esta versión solo puede avisar mientras la app está abierta y el navegador permite hacerlo.</p><div class="actions"><button @click="requestPermission">Solicitar permiso</button><button class="secondary" @click="testSound">Probar sonido</button></div><label class="toggle"><input v-model="soundEnabled" type="checkbox" /> Activar sonido en alertas abiertas</label><p v-if="message" class="message">{{ message }}</p></section></div>
</template>
<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'; import TopBar from '~/components/TopBar.vue'
const permission = ref('desconocido'); const serviceWorker = ref('comprobando'); const soundEnabled = ref(true); const message = ref('')
const requestPermission = async () => { if (!('Notification' in window)) { permission.value = 'no compatible'; return }; permission.value = await Notification.requestPermission(); if (permission.value === 'granted') new Notification('Finanzas', { body: 'Las notificaciones están activas.' }) }
const testSound = () => { if (!soundEnabled.value) { message.value = 'Activa el sonido primero.'; return }; const context = new AudioContext(); const oscillator = context.createOscillator(); const gain = context.createGain(); oscillator.frequency.value = 660; gain.gain.value = 0.05; oscillator.connect(gain); gain.connect(context.destination); oscillator.start(); oscillator.stop(context.currentTime + .25); message.value = 'Sonido reproducido. El navegador puede bloquear audio no iniciado por una acción.' }
watch(soundEnabled, (enabled) => localStorage.setItem('payment-sound-enabled', String(enabled)))
onMounted(async () => { permission.value = 'Notification' in window ? Notification.permission : 'no compatible'; soundEnabled.value = localStorage.getItem('payment-sound-enabled') !== 'false'; serviceWorker.value = 'serviceWorker' in navigator ? (await navigator.serviceWorker.getRegistration() ? 'activo o registrado' : 'no registrado') : 'no compatible' })
</script>
<style scoped>.container{max-width:800px;margin:auto;color:#fff}.card{background:#111827;border:1px solid #263244;border-radius:18px;padding:18px}.actions{display:flex;gap:10px;margin:18px 0}.actions button{padding:11px 14px;border:0;border-radius:10px;background:#2563eb;color:#fff;font-weight:800}.actions .secondary{background:#334155}.toggle{display:block;margin-top:12px}.message{color:#93c5fd}@media(max-width:600px){.actions{flex-direction:column}}
</style>
